#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    double a{}, b{}, c{}, d{}, e{}, f{};
    if (!(std::cin >> a >> b >> c >> d >> e >> f)) {
        return 0;
    }

    double det = a * d - b * c;
    if (std::abs(det) < 1e-12) {
        std::cout << "The equation has no solution\n";
    } else {
        double x = (e * d - b * f) / det;
        double y = (a * f - e * c) / det;
        if (std::abs(x) < 1e-12) x = 0.0;
        if (std::abs(y) < 1e-12) y = 0.0;
        std::cout << std::fixed << std::setprecision(1);
        std::cout << "x is " << x << " and y is " << y << "\n";
    }
    return 0;
}

#include <iostream>
#include <cmath>

int main() {
    double x{}, y{};
    if (!(std::cin >> x >> y)) {
        return 0;
    }

    const double radius = 10.0;
    bool inCircle = (x * x + y * y) <= (radius * radius);

    const double halfWidth = 10.0 / 2.0;
    const double halfHeight = 5.0 / 2.0;
    bool inRectangle = (std::abs(x) <= halfWidth) && (std::abs(y) <= halfHeight);

    std::cout << "Point (" << x << ", " << y << ") is "
              << (inCircle ? "in" : "not in") << " the circle\n";
    std::cout << "Point (" << x << ", " << y << ") is "
              << (inRectangle ? "in" : "not in") << " the rectangle\n";

    return 0;
}
